  // lib/codec/base32.ts
  var ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  function base32Decode(s) {
    let bits = 0;
    let value = 0;
    const out = [];
    for (const ch of s.replace(/=+$/, "")) {
      const idx = ALPHABET.indexOf(ch);
      if (idx < 0) return null;
      value = value << 5 | idx;
      bits += 5;
      if (bits >= 8) {
        bits -= 8;
        out.push(value >>> bits & 255);
      }
    }
    return Uint8Array.from(out);
  }
  function crc16xmodem(bytes) {
    let crc = 0;
    for (const b of bytes) {
      crc ^= b << 8;
      for (let i = 0; i < 8; i++) crc = crc & 32768 ? (crc << 1 ^ 4129) & 65535 : crc << 1 & 65535;
    }
    return crc;
  }

  // lib/codec/bytes.ts
  function hexToBytes(hex) {
    let h2 = hex.trim().replace(/^0x/i, "");
    if (!/^[0-9a-f]*$/i.test(h2)) throw new Error("Not a hex string");
    if (h2.length % 2) h2 = `0${h2}`;
    const out = new Uint8Array(h2.length / 2);
    for (let i = 0; i < out.length; i++) out[i] = parseInt(h2.slice(i * 2, i * 2 + 2), 16);
    return out;
  }
  function bytesToHex(bytes, prefix = true) {
    let s = "";
    for (const b of bytes) s += b.toString(16).padStart(2, "0");
    return prefix ? `0x${s}` : s;
  }
  function utf8ToBytes(s) {
    return new TextEncoder().encode(s);
  }
  function bytesToUtf8(bytes) {
    try {
      return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    } catch {
      return null;
    }
  }
  function concatBytes(...parts) {
    const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
    let o = 0;
    for (const p of parts) {
      out.set(p, o);
      o += p.length;
    }
    return out;
  }
  function equalBytes(a, b) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
    return true;
  }
  function bytesToBigInt(bytes) {
    let n = BigInt(0);
    for (const b of bytes) n = n << BigInt(8) | BigInt(b);
    return n;
  }
  function bigIntToBytes(n, length) {
    if (n < BigInt(0)) throw new Error("Negative");
    let hex = n.toString(16);
    if (hex.length % 2) hex = `0${hex}`;
    const raw = hexToBytes(hex === "00" && length === 0 ? "" : hex);
    if (length === void 0) return raw;
    if (raw.length > length) throw new Error("Number too large");
    const out = new Uint8Array(length);
    out.set(raw, length - raw.length);
    return out;
  }

